          bias_ptr,
          y.data_ptr<float>(),
          (int)N, (int)C_in, (int)C_out,
          (int)A, (int)B, (int)E,
          (int)A_out, (int)B_out, (int)E_out,
          (int)K, (int)stride, (int)padding, (int)dilation,
