class ModelNew(nn.Module):
    """
    3D convolution with kernel (kernel_size, kernel_size, 1) implemented with a single
    cooperative tiled CuTe/CUDA kernel. Parameters are stored in an nn.Conv3d submodule
    so that initialization and state_dict are identical to the reference model, while
    all computation in forward() is performed by the custom CuTe kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
