cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Tiled cooperative 3D convolution kernel for kernel shape (K, K, 1), groups == 1.
// Input  X: [N, C_in, A, B, E]   (PyTorch NCDHW ordering)
// Weight W: [C_out, C_in, K, K, 1]
// Output Y: [N, C_out, A_out, B_out, E_out]
//
// Because the kernel extent along the last spatial dim is 1, the depth (E)
// dimension is a pure batch-like, contiguous dimension. Each thread block
// cooperatively computes a (tileA x tileB x tileE) output tile for tileOC
// output channels of one batch image, staging the receptive input tile and
// the weights in shared memory via CuTe tensors. The fastest-varying threads
// are mapped to the contiguous E dimension so that all global-memory loads
// and stores are fully coalesced (the previous version mapped them to the
// strided A dimension, causing severely uncoalesced global traffic).
template <typename T, int Threads, int ME, int KS>
__global__ void conv3d_kk1_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int C_in, int C_out,
    int A, int B, int E,
    int A_out, int B_out, int E_out,
    int K, int stride, int padding, int dilation,
    int tileA, int tileB, int tileOC, int chunkC,
    int tsA, int tsB, int tileE, int tsE,
    int aTiles, int bTiles, int eTiles)
{
  // Per-thread micro tile: 2x2 spatial x 8 output channels x ME depth slices.
  // ME is a template parameter so shallow-depth problems can avoid computing a
  // second, entirely guarded depth slice while keeping the same thread layout.
  constexpr int MA  = 2;
  constexpr int MB  = 2;
  constexpr int MOC = 8;
  // Thread layout: 8 (A) x 4 (B) spatial threads x 10 (E) depth threads = 320.
  // E is the innermost contiguous dimension, hence the fastest thread index.
  // For ME=2, thread te_t covers depth offsets te_t and te_t + TE_T within
  // the tile; for ME=1 it covers only te_t, which exactly matches shallow depth.
  constexpr int TA_T = 8;
  constexpr int TB_T = 4;
  constexpr int TE_T = 10;
  static_assert(Threads == TA_T * TB_T * TE_T, "thread layout mismatch");
  static_assert(ME == 1 || ME == 2, "ME must be 1 or 2");
  static_assert(KS == 0 || KS == 3, "KS must be 0 (generic) or 3 (unrolled fast path)");
  // Decode block coordinates.
  const int ab_tiles = aTiles * bTiles;
  const int tile_ab  = blockIdx.x % ab_tiles;
  const int nz       = blockIdx.x / ab_tiles;
  const int ta       = tile_ab % aTiles;
  const int tb       = tile_ab / aTiles;
  const int n        = nz / eTiles;
  const int te_blk   = nz % eTiles;
  const int a0  = ta * tileA;
  const int b0  = tb * tileB;
  const int e0  = te_blk * tileE;
  const int oc0 = blockIdx.y * tileOC;
  const int64_t sXn = (int64_t)C_in * A * B * E;
  const int64_t sXc = (int64_t)A * B * E;
  const int64_t sXa = (int64_t)B * E;
  const int64_t sXb = (int64_t)E;
  const int64_t sYn = (int64_t)C_out * A_out * B_out * E_out;
  const int64_t sYc = (int64_t)A_out * B_out * E_out;
  const int64_t sYa = (int64_t)B_out * E_out;
  const int64_t sYb = (int64_t)E_out;
  // Global CuTe tensors, exposing the contiguous depth dimension.
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                        make_shape(C_in, A, B, E),
                        make_stride(sXc, sXa, sXb, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                        make_shape(C_out, A_out, B_out, E_out),
                        make_stride(sYc, sYa, sYb, Int<1>{}));
  const int KK = K * K;
  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(C_out, C_in, KK),
                        make_stride((int64_t)C_in * KK, (int64_t)KK, Int<1>{}));
  // Dynamic shared memory staged via CuTe tensors. The depth stride of the
  // staged input tile is padded to an odd value to keep the per-thread
  // depth lanes on distinct shared-memory banks.
  const int tsE_smem = tsE + ((tsE % 2 == 0) ? 1 : 0);
  extern __shared__ __align__(16) float smem[];
  float* sX_raw = smem;
  float* sW_raw = smem + (int64_t)chunkC * tsA * tsB * tsE_smem;
  auto sX = make_tensor(make_smem_ptr(sX_raw),
                        make_shape(chunkC, tsA, tsB, tsE),
                        make_stride((int64_t)tsA * tsB * tsE_smem,
                                    (int64_t)tsB * tsE_smem,
                                    (int64_t)tsE_smem, Int<1>{}));
  auto sW = make_tensor(make_smem_ptr(sW_raw),
                        make_shape(tileOC, chunkC, KK),
                        make_stride((int64_t)chunkC * KK, (int64_t)KK, Int<1>{}));
  const int tid  = threadIdx.x;
  const int te_t = tid % TE_T;
  const int tb_t = (tid / TE_T) % TB_T;
  const int ta_t = tid / (TE_T * TB_T);
  // Accumulators initialized with bias (if present).
  float acc[MOC][MA][MB][ME];
  #pragma unroll
  for (int o = 0; o < MOC; ++o) {
    const int oc = oc0 + o;
    const float bv = (Bias != nullptr && oc < C_out) ? (float)Bias[oc] : 0.0f;
    #pragma unroll
    for (int i = 0; i < MA; ++i)
      #pragma unroll
      for (int j = 0; j < MB; ++j)
        #pragma unroll
        for (int me = 0; me < ME; ++me)
          acc[o][i][j][me] = bv;
  }
  const int la_base = ta_t * MA * stride;
  const int lb_base = tb_t * MB * stride;
  const int le_base = te_t * stride;
  // Origins of the receptive input tile for this output tile.
  const int a_in0 = a0 * stride - padding;
  const int b_in0 = b0 * stride - padding;
  const int e_in0 = e0 * stride - padding;
  for (int c0 = 0; c0 < C_in; c0 += chunkC) {
    // Cooperative load of the weight chunk into shared memory.
    {
      const int total = tileOC * chunkC * KK;
      for (int idx = tid; idx < total; idx += Threads) {
        const int kk = idx % KK;
        const int cc = (idx / KK) % chunkC;
        const int oo = idx / (KK * chunkC);
        const int oc = oc0 + oo;
        const int ic = c0 + cc;
        float v = 0.0f;
        if (oc < C_out && ic < C_in) v = (float)mW(oc, ic, kk);
        sW(oo, cc, kk) = v;
      }
    }
    // Cooperative load of the receptive input tile into shared memory.
    // Depth is the fastest-varying index, so global reads are coalesced.
    {
      const int total = chunkC * tsA * tsB * tsE;
      for (int idx = tid; idx < total; idx += Threads) {
        const int ee = idx % tsE;
        const int bb = (idx / tsE) % tsB;
        const int aa = (idx / (tsE * tsB)) % tsA;
        const int cc = idx / (tsE * tsB * tsA);
        const int ic   = c0 + cc;
        const int a_in = a_in0 + aa;
        const int b_in = b_in0 + bb;
        const int e_in = e_in0 + ee;
        float v = 0.0f;
        if (ic < C_in &&
            a_in >= 0 && a_in < A &&
            b_in >= 0 && b_in < B &&
            e_in >= 0 && e_in < E) {
          v = (float)mX(ic, a_in, b_in, e_in);
        }
        sX(cc, aa, bb, ee) = v;
      }
    }
    __syncthreads();
    // Compute on the staged chunk.
    const int cc_max = min(chunkC, C_in - c0);
    if (KS == 3) {
      // Fast path (K==3, stride==1, dilation==1): stage the per-thread
      // (MA+2)x(MB+2) receptive window in registers once per input channel
      // and fully unroll the 3x3 kernel loop, so overlapping halo elements
      // are read back from registers instead of shared memory and all
      // window addressing folds into compile-time register indexing.
      const int la0 = la_base;  // stride == 1
      const int lb0 = lb_base;  // stride == 1
      for (int cc = 0; cc < cc_max; ++cc) {
        float win[ME][MA + KS - 1][MB + KS - 1];
        #pragma unroll
        for (int me = 0; me < ME; ++me) {
          const int le = le_base + me * TE_T;  // stride == 1
          #pragma unroll
          for (int r = 0; r < MA + KS - 1; ++r) {
            #pragma unroll
            for (int q = 0; q < MB + KS - 1; ++q) {
              win[me][r][q] = sX(cc, la0 + r, lb0 + q, le);
            }
          }
        }
        #pragma unroll
        for (int ka = 0; ka < KS; ++ka) {
          #pragma unroll
          for (int kb = 0; kb < KS; ++kb) {
            float wv[MOC];
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              wv[o] = sW(o, cc, ka * KS + kb);
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              #pragma unroll
              for (int me = 0; me < ME; ++me)
                #pragma unroll
                for (int i = 0; i < MA; ++i)
                  #pragma unroll
                  for (int j = 0; j < MB; ++j)
                    acc[o][i][j][me] += win[me][i + ka][j + kb] * wv[o];
          }
        }
      }
    } else {
      for (int cc = 0; cc < cc_max; ++cc) {
        for (int ka = 0; ka < K; ++ka) {
          const int la_k = ka * dilation;
          for (int kb = 0; kb < K; ++kb) {
            const int lb_k = kb * dilation;
            float xv[ME][MA][MB];
            #pragma unroll
            for (int me = 0; me < ME; ++me) {
              const int le = le_base + me * TE_T * stride;
              #pragma unroll
              for (int i = 0; i < MA; ++i) {
                const int la = la_base + i * stride + la_k;
                #pragma unroll
                for (int j = 0; j < MB; ++j) {
                  const int lb = lb_base + j * stride + lb_k;
                  xv[me][i][j] = sX(cc, la, lb, le);
                }
              }
            }
            float wv[MOC];
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              wv[o] = sW(o, cc, ka * K + kb);
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              #pragma unroll
              for (int me = 0; me < ME; ++me)
                #pragma unroll
                for (int i = 0; i < MA; ++i)
                  #pragma unroll
                  for (int j = 0; j < MB; ++j)
                    acc[o][i][j][me] += xv[me][i][j] * wv[o];
          }
        }
      }
    }
    __syncthreads();
  }
  // Epilogue: guarded store of the output tile. Within each depth slice,
  // consecutive threads write consecutive depth positions, so global
  // stores are coalesced.
  #pragma unroll
  for (int me = 0; me < ME; ++me) {
    const int e_out = e0 + te_t + me * TE_T;
    if (e_out < E_out) {
      #pragma unroll
      for (int o = 0; o < MOC; ++o) {
        const int oc = oc0 + o;
        if (oc >= C_out) continue;
        #pragma unroll
        for (int i = 0; i < MA; ++i) {
