// Single-input-chunk specialization: stage the receptive input tile once, then loop
// over all output-channel tiles inside the block. For tiny C_in (the benchmark uses
// C_in=3), the old grid.y=ocTiles layout reloaded the same input tile once per
// output-channel tile. Keeping sX resident across the oc-tile loop removes that
// repeated global-memory input traffic while preserving the same per-oc-tile
// register blocking and guarded stores.
template <typename T, int Threads, int ME, int KS>
__global__ void conv3d_kk1_tiled_all_oc_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int C_in, int C_out,
    int A, int B, int E,
    int A_out, int B_out, int E_out,
    int K, int stride, int padding, int dilation,
    int tileA, int tileB, int tileOC, int chunkC,
    int tsA, int tsB, int tileE, int tsE,
    int aTiles, int bTiles, int eTiles, int ocTiles)
