  const int tile_ab  = blockIdx.x % ab_tiles;
  const int nz       = blockIdx.x / ab_tiles;
  const int ta       = tile_ab % aTiles;
  const int tb       = tile_ab / aTiles;
  const int n        = nz / eTiles;
  const int te_blk   = nz % eTiles;
  const int a0  = ta * tileA;
  const int b0  = tb * tileB;
  const int e0  = te_blk * tileE;
  const int64_t sXn = (int64_t)C_in * A * B * E;
  const int64_t sXc = (int64_t)A * B * E;
  const int64_t sXa = (int64_t)B * E;
  const int64_t sXb = (int64_t)E;
  const int64_t sYn = (int64_t)C_out * A_out * B_out * E_out;
  const int64_t sYc = (int64_t)A_out * B_out * E_out;
  const int64_t sYa = (int64_t)B_out * E_out;
  const int64_t sYb = (int64_t)E_out;
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                        make_shape(C_in, A, B, E),
                        make_stride(sXc, sXa, sXb, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                        make_shape(C_out, A_out, B_out, E_out),
                        make_stride(sYc, sYa, sYb, Int<1>{}));
  const int KK = K * K;
  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(C_out, C_in, KK),
                        make_stride((int64_t)C_in * KK, (int64_t)KK, Int<1>{}));
  const int tsE_smem = tsE + ((tsE % 2 == 0) ? 1 : 0);
  extern __shared__ __align__(16) float smem[];
  float* sX_raw = smem;
  float* sW_raw = smem + (int64_t)chunkC * tsA * tsB * tsE_smem;
  auto sX = make_tensor(make_smem_ptr(sX_raw),
                        make_shape(chunkC, tsA, tsB, tsE),
                        make_stride((int64_t)tsA * tsB * tsE_smem,
                                    (int64_t)tsB * tsE_smem,
                                    (int64_t)tsE_smem, Int<1>{}));
