        if (oc < C_out && cc < C_in) v = (float)mW(oc, cc, kk);
        sW(oo, cc, kk) = v;
      }
    }
    __syncthreads();
    float acc[MOC][MA][MB][ME];
    #pragma unroll
    for (int o = 0; o < MOC; ++o) {
      const int oc = oc0 + o;
      const float bv = (Bias != nullptr && oc < C_out) ? (float)Bias[oc] : 0.0f;
      #pragma unroll
      for (int i = 0; i < MA; ++i)
        #pragma unroll
        for (int j = 0; j < MB; ++j)
          #pragma unroll
          for (int me = 0; me < ME; ++me)
            acc[o][i][j][me] = bv;
    }
    if (KS == 3) {
      const int la0 = la_base;
      const int lb0 = lb_base;
      for (int cc = 0; cc < cc_max; ++cc) {
        float win[ME][MA + KS - 1][MB + KS - 1];
        #pragma unroll
        for (int me = 0; me < ME; ++me) {
          const int le = le_base + me * TE_T;
          #pragma unroll
          for (int r = 0; r < MA + KS - 1; ++r) {
            #pragma unroll
            for (int q = 0; q < MB + KS - 1; ++q) {
              win[me][r][q] = sX(cc, la0 + r, lb0 + q, le);
            }
          }
        }
        #pragma unroll
        for (int ka = 0; ka < KS; ++ka) {
          #pragma unroll
          for (int kb = 0; kb < KS; ++kb) {
            float wv[MOC];
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              wv[o] = sW(o, cc, ka * KS + kb);
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              #pragma unroll
              for (int me = 0; me < ME; ++me)
                #pragma unroll
                for (int i = 0; i < MA; ++i)
                  #pragma unroll
                  for (int j = 0; j < MB; ++j)
                    acc[o][i][j][me] += win[me][i + ka][j + kb] * wv[o];
          }
        }
      }
    } else {
      for (int cc = 0; cc < cc_max; ++cc) {
        for (int ka = 0; ka < K; ++ka) {
          const int la_k = ka * dilation;
          for (int kb = 0; kb < K; ++kb) {
            const int lb_k = kb * dilation;
            float xv[ME][MA][MB];
            #pragma unroll
            for (int me = 0; me < ME; ++me) {
              const int le = le_base + me * TE_T * stride;
              #pragma unroll
              for (int i = 0; i < MA; ++i) {
                const int la = la_base + i * stride + la_k;
                #pragma unroll
                for (int j = 0; j < MB; ++j) {
                  const int lb = lb_base + j * stride + lb_k;
                  xv[me][i][j] = sX(cc, la, lb, le);
                }
              }
            }
            float wv[MOC];
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              wv[o] = sW(o, cc, ka * K + kb);
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              #pragma unroll
              for (int me = 0; me < ME; ++me)
                #pragma unroll
                for (int i = 0; i < MA; ++i)
                  #pragma unroll
                  for (int j = 0; j < MB; ++j)
                    acc[o][i][j][me] += xv[me][i][j] * wv[o];
          }
        }
      }
    }
    #pragma unroll
    for (int me = 0; me < ME; ++me) {
      const int e_out = e0 + te_t + me * TE_T;
      if (e_out < E_out) {
        #pragma unroll
        for (int o = 0; o < MOC; ++o) {
          const int oc = oc0 + o;
          if (oc >= C_out) continue;
          #pragma unroll
          for (int i = 0; i < MA; ++i) {
            const int a = a0 + ta_t * MA + i;
            if (a >= A_out) continue;
            #pragma unroll
            for (int j = 0; j < MB; ++j) {
              const int b = b0 + tb_t * MB + j;
              if (b >= B_out) continue;
              mY(oc, a, b, e_out) = (T)acc[o][i][j][me];
            }
          }
        }
      }
    }
    __syncthreads();
  }
}
torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> bias,
                                 int64_t stride,
                                 int64_t padding,
