// Tiled cooperative 3D convolution kernel for kernel shape (K, K, 1), groups == 1.
// Input  X: [N, C_in, A, B, E]   (PyTorch NCDHW ordering)
// Weight W: [C_out, C_in, K, K, 1]
// Output Y: [N, C_out, A_out, B_out, E_out]
//
// Because the kernel extent along the last spatial dim is 1, the depth (E)
// dimension is a pure batch-like, contiguous dimension. Each thread block
// cooperatively computes a (tileA x tileB x tileE) output tile for tileOC
// output channels of one batch image, staging the receptive input tile and
// the weights in shared memory via CuTe tensors. The fastest-varying threads
// are mapped to the contiguous E dimension so that all global-memory loads
// and stores are fully coalesced (the previous version mapped them to the
// strided A dimension, causing severely uncoalesced global traffic).
template <typename T, int Threads, int ME, int KS>
__global__ void conv3d_kk1_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int C_in, int C_out,
    int A, int B, int E,
    int A_out, int B_out, int E_out,
    int K, int stride, int padding, int dilation,
    int tileA, int tileB, int tileOC, int chunkC,
    int tsA, int tsB, int tileE, int tsE,
    int aTiles, int bTiles, int eTiles)
{
