      const int ee = idx % tsE;
      const int bb = (idx / tsE) % tsB;
      const int aa = (idx / (tsE * tsB)) % tsA;
      const int cc = idx / (tsE * tsB * tsA);
      const int a_in = a_in0 + aa;
      const int b_in = b_in0 + bb;
      const int e_in = e_in0 + ee;
