    const int oc0 = oct * tileOC;
    {
      const int total = tileOC * chunkC * KK;
      for (int idx = tid; idx < total; idx += Threads) {
        const int kk = idx % KK;
        const int cc = (idx / KK) % chunkC;
        const int oo = idx / (KK * chunkC);
        const int oc = oc0 + oo;
        float v = 0.0f;
        if (oc < C_out && cc < C_in) v = (float)mW(oc, cc, kk);
