      }
    }
    __syncthreads();
    float acc[MOC][MA][MB][ME];
    #pragma unroll
    for (int o = 0; o < MOC; ++o) {
      const int oc = oc0 + o;
      const float bv = (Bias != nullptr && oc < C_out) ? (float)Bias[oc] : 0.0f;
      #pragma unroll
      for (int i = 0; i < MA; ++i)
        #pragma unroll
        for (int j = 0; j < MB; ++j)
          #pragma unroll
          for (int me = 0; me < ME; ++me)
            acc[o][i][j][me] = bv;
    }
    if (KS == 3) {
      const int la0 = la_base;
      const int lb0 = lb_base;
      for (int cc = 0; cc < cc_max; ++cc) {
        float win[ME][MA + KS - 1][MB + KS - 1];
        #pragma unroll
        for (int me = 0; me < ME; ++me) {
          const int le = le_base + me * TE_T;
          #pragma unroll
          for (int r = 0; r < MA + KS - 1; ++r) {
            #pragma unroll
            for (int q = 0; q < MB + KS - 1; ++q) {
              win[me][r][q] = sX(cc, la0 + r, lb0 + q, le);
            }
          }
        }
        #pragma unroll
        for (int ka = 0; ka < KS; ++ka) {
          #pragma unroll
          for (int kb = 0; kb < KS; ++kb) {
            float wv[MOC];
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              wv[o] = sW(o, cc, ka * KS + kb);
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              #pragma unroll
              for (int me = 0; me < ME; ++me)
                #pragma unroll
                for (int i = 0; i < MA; ++i)
                  #pragma unroll
                  for (int j = 0; j < MB; ++j)
                    acc[o][i][j][me] += win[me][i + ka][j + kb] * wv[o];
          }
        }
      }
    } else {
      for (int cc = 0; cc < cc_max; ++cc) {
        for (int ka = 0; ka < K; ++ka) {
          const int la_k = ka * dilation;
          for (int kb = 0; kb < K; ++kb) {
            const int lb_k = kb * dilation;
            float xv[ME][MA][MB];
            #pragma unroll
            for (int me = 0; me < ME; ++me) {
              const int le = le_base + me * TE_T * stride;
              #pragma unroll
              for (int i = 0; i < MA; ++i) {
                const int la = la_base + i * stride + la_k;
                #pragma unroll
                for (int j = 0; j < MB; ++j) {
                  const int lb = lb_base + j * stride + lb_k;
                  xv[me][i][j] = sX(cc, la, lb, le);
                }
              }
            }
            float wv[MOC];
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              wv[o] = sW(o, cc, ka * K + kb);
            #pragma unroll
            for (int o = 0; o < MOC; ++o)
              #pragma unroll
              for (int me = 0; me < ME; ++me)
                #pragma unroll
                for (int i = 0; i < MA; ++i)
                  #pragma unroll
                  for (int j = 0; j < MB; ++j)
                    acc[o][i][j][me] += xv[me][i][j] * wv[o];
          }
        }
      }
    }
    #pragma unroll
    for (int me = 0; me < ME; ++me) {
      const int e_out = e0 + te_t + me * TE_T;
      if (e_out < E_out) {
        #pragma unroll
        for (int o = 0; o < MOC; ++o) {
          const int oc = oc0 + o;
          if (oc >= C_out) continue;
          #pragma unroll
          for (int i = 0; i < MA; ++i) {
            const int a = a0 + ta_t * MA + i;
            if (a >= A_out) continue;
            #pragma unroll
            for (int j = 0; j < MB; ++j) {
              const int b = b0 + tb_t * MB + j;
              if (b >= B_out) continue;
              mY(oc, a, b, e_out) = (T)acc[o][i][j][me];
            }
          }
        }
      }
    }
    __syncthreads();
  }
}
torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> bias,
                                 int64_t stride,
                                 int64_t padding,
                                 int64_t dilation) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be 5D [N, C_in, A, B, E]");
  TORCH_CHECK(w.dim() == 5, "w must be 5D [C_out, C_in, K, K, 1]");
  TORCH_CHECK(stride >= 1 && dilation >= 1 && padding >= 0,
              "invalid stride/padding/dilation");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N    = x_c.size(0);
  const int64_t C_in = x_c.size(1);
  const int64_t A    = x_c.size(2);
  const int64_t B    = x_c.size(3);
  const int64_t E    = x_c.size(4);

  const int64_t C_out = w_c.size(0);
  TORCH_CHECK(w_c.size(1) == C_in, "groups must be 1 (w.size(1) == C_in)");
  const int64_t K = w_c.size(2);
  TORCH_CHECK(w_c.size(3) == K && w_c.size(4) == 1, "kernel must be (K, K, 1)");
  TORCH_CHECK(K >= 1, "kernel size must be >= 1");

  const float* bias_ptr = nullptr;
  torch::Tensor b_c;
  if (bias.has_value() && bias->defined()) {
    b_c = bias->contiguous();
    TORCH_CHECK(b_c.scalar_type() == at::kFloat && b_c.dim() == 1 && b_c.size(0) == C_out,
                "bias must be float32 of shape [C_out]");
    bias_ptr = b_c.data_ptr<float>();
  }

  const int64_t A_out = (A + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  const int64_t B_out = (B + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  const int64_t E_out = (E + 2 * padding - 1) / stride + 1;  // kernel extent 1 on E
  TORCH_CHECK(A_out > 0 && B_out > 0 && E_out > 0, "invalid output size");

  auto y = torch::empty({N, C_out, A_out, B_out, E_out}, x_c.options());

  constexpr int Threads = 320;
  constexpr int tileA   = 16;   // 8 threads  x 2 outputs
  constexpr int tileB   = 8;    // 4 threads  x 2 outputs
  constexpr int tileOC  = 8;    // 8 output channels per block
  const int chunkC = (C_in < 4) ? (int)C_in : 4;  // avoid staging a dead input channel for tiny C_in
  const bool single_chunk = (C_in <= (int64_t)chunkC);  // enables input-tile reuse across all output-channel tiles
  constexpr int TE_T    = 10;
  const int64_t tsA = (tileA - 1) * stride + dilation * (K - 1) + 1;
  const int64_t tsB = (tileB - 1) * stride + dilation * (K - 1) + 1;
  const int64_t aTiles  = (A_out + tileA - 1) / tileA;
  const int64_t bTiles  = (B_out + tileB - 1) / tileB;
  const int64_t ocTiles = (C_out + tileOC - 1) / tileOC;
  TORCH_CHECK(ocTiles <= 65535, "too many output-channel tiles");
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  // The K==3, stride==1, dilation==1 configuration (the benchmark case) uses
  // a fully unrolled register-window fast path inside the same tiled kernel.
  const bool fast_path = (K == 3 && stride == 1 && dilation == 1);
  dim3 block(Threads);
  // Shape-aware depth tiling: the benchmark shape has depth 10, so the old
  // ME=2/tileE=20 configuration made every thread compute a second fully
  // guarded depth slice.  Specialize the same cooperative kernel with ME=1
  // for shallow depth, eliminating that wasted half of the FMAs, staged tile
  // traffic, and guarded stores while preserving the general ME=2 path.
  if (E_out <= TE_T) {
    constexpr int tileE = TE_T;   // one depth slice per thread
    const int64_t tsE = (tileE - 1) * stride + 1;  // kernel extent 1 on E
    const int64_t tsE_smem = tsE + ((tsE % 2 == 0) ? 1 : 0);
    const int64_t eTiles = (E_out + tileE - 1) / tileE;
    const int64_t smem_floats = (int64_t)chunkC * tsA * tsB * tsE_smem
                              + (int64_t)tileOC * chunkC * K * K;
    const int64_t smem_bytes  = smem_floats * (int64_t)sizeof(float);
    TORCH_CHECK(smem_bytes <= 200 * 1024, "shared memory requirement too large");
    if (single_chunk) {
      auto kernel = fast_path ? conv3d_kk1_tiled_all_oc_kernel<float, Threads, 1, 3> : conv3d_kk1_tiled_all_oc_kernel<float, Threads, 1, 0>;
      if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
      }
      dim3 grid((unsigned)(aTiles * bTiles * eTiles * N), 1, 1);
      kernel<<<grid, block, (size_t)smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          bias_ptr,
          y.data_ptr<float>(),
          (int)N, (int)C_in, (int)C_out,
          (int)A, (int)B, (int)E,
          (int)A_out, (int)B_out, (int)E_out,
          (int)K, (int)stride, (int)padding, (int)dilation,
          tileA, tileB, tileOC, chunkC,
          (int)tsA, (int)tsB, tileE, (int)tsE,
          (int)aTiles, (int)bTiles, (int)eTiles, (int)ocTiles);
    } else {
      auto kernel = fast_path ? conv3d_kk1_tiled_kernel<float, Threads, 1, 3> : conv3d_kk1_tiled_kernel<float, Threads, 1, 0>;
      if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
      }
      dim3 grid((unsigned)(aTiles * bTiles * eTiles * N), (unsigned)ocTiles, 1);
      kernel<<<grid, block, (size_t)smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          bias_ptr,
          y.data_ptr<float>(),
          (int)N, (int)C_in, (int)C_out,
          (int)A, (int)B, (int)E,
          (int)A_out, (int)B_out, (int)E_out,
          (int)K, (int)stride, (int)padding, (int)dilation,
          tileA, tileB, tileOC, chunkC,
          (int)tsA, (int)tsB, tileE, (int)tsE,
          (int)aTiles, (int)bTiles, (int)eTiles);
    }
  } else {
    constexpr int tileE = 20;   // 10 depth threads x ME=2 depth slices per thread
    const int64_t tsE = (tileE - 1) * stride + 1;  // kernel extent 1 on E
    const int64_t tsE_smem = tsE + ((tsE % 2 == 0) ? 1 : 0);
    const int64_t eTiles = (E_out + tileE - 1) / tileE;
    const int64_t smem_floats = (int64_t)chunkC * tsA * tsB * tsE_smem
                              + (int64_t)tileOC * chunkC * K * K;
    const int64_t smem_bytes  = smem_floats * (int64_t)sizeof(float);
    TORCH_CHECK(smem_bytes <= 200 * 1024, "shared memory requirement too large");
    if (single_chunk) {
      auto kernel = fast_path ? conv3d_kk1_tiled_all_oc_kernel<float, Threads, 2, 3> : conv3d_kk1_tiled_all_oc_kernel<float, Threads, 2, 0>;
      if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
      }
      dim3 grid((unsigned)(aTiles * bTiles * eTiles * N), 1, 1);
      kernel<<<grid, block, (size_t)smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          bias_ptr,
          y.data_ptr<float>(),
          (int)N, (int)C_in, (int)C_out,
          (int)A, (int)B, (int)E,
          (int)A_out, (int)B_out, (int)E_out,
          (int)K, (int)stride, (int)padding, (int)dilation,
          tileA, tileB, tileOC, chunkC,
          (int)tsA, (int)tsB, tileE, (int)tsE,
          (int)aTiles, (int)bTiles, (int)eTiles, (int)ocTiles);
    } else {
      auto kernel = fast_path ? conv3d_kk1_tiled_kernel<float, Threads, 2, 3> : conv3d_kk1_tiled_kernel<float, Threads, 2, 0>;
      if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
      }
      dim3 grid((unsigned)(aTiles * bTiles * eTiles * N), (unsigned)ocTiles, 1);
      kernel<<<grid, block, (size_t)smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          bias_ptr,
          y.data_ptr<float>(),
          (int)N, (int)C_in, (int)C_out,
          (int)A, (int)B, (int)E,
          (int)A_out, (int)B_out, (int)E_out,
          (int)K, (int)stride, (int)padding, (int)dilation,
          tileA, tileB, tileOC, chunkC,
          (int)tsA, (int)tsB, tileE, (int)tsE,
          (int)aTiles, (int)bTiles, (int)eTiles);
    }
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kk1_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
