    def forward(self, x: torch.Tensor) -> torch.Tensor:
        st = self.conv3d.stride
        pd = self.conv3d.padding
        dl = self.conv3d.dilation
        if (self.conv3d.groups == 1
                and st[0] == st[1] == st[2]
                and pd[0] == pd[1] == pd[2]
                and dl[0] == dl[1] == dl[2]
